const sections = document.querySelectorAll("header, section");
const sectionCount = sections.length;

console.log(sections)

let previousSection = null;
let isScrolling = false;
let targetSection = 0;   // where we're currently traveling

let currentSection = Math.floor(window.scrollY / window.innerHeight)

// For animations.js
export { sections, sectionCount };



// ==============================
// DESKTOP MOUSE WHEEL
// ==============================

window.addEventListener("wheel", function(event){


    const canvas3D = document.getElementById("modelingCanvas");
    const canvasPrint = document.getElementById("printingCanvas");


    const mouseOver3D =
        canvas3D && canvas3D.matches(":hover");


    const mouseOverPrint =
        canvasPrint && canvasPrint.matches(":hover");



    // Allow CTRL + wheel zoom inside canvases
    if(event.ctrlKey){

        return;

    }

    if(mouseOver3D || mouseOverPrint){

        return;

    }



    event.preventDefault();



    if(isScrolling){

        return;

    }

    updatePreviouseSection();
    updateCurrentSection();
    
    
    
    if(event.deltaY > 0){   
        
        currentSection++;
        
    }
    else{
        
        currentSection--;
        
    }
    
    
    clampSection();


    scrollToSection(currentSection);



}, { passive:false });





// ============================== ==============================

// ============================== ==============================
// MOBILE TOUCH 
// ============================== ==============================

// ============================== ==============================


let touchStartY = 0;
let touchEndY = 0;



window.addEventListener("touchstart", function(event){


    if(isScrolling){
        return;
    }


    touchStartY = event.touches[0].clientY;


}, {passive:false});





window.addEventListener("touchmove", function(event){


    event.preventDefault();


}, {passive:false});






window.addEventListener("touchend", function(event){


    if(isScrolling){
        return;
    }



    touchEndY = event.changedTouches[0].clientY;



    const distance = touchStartY - touchEndY;



    // Ignore small touches
    if(Math.abs(distance) < 70){

        return;

    }


    updatePreviouseSection();
    updateCurrentSection();



    if(distance > 0){

        currentSection++;

    }
    else{

        currentSection--;


    }



    clampSection();


    scrollToSection(currentSection);

    designAnimation();



}, {passive:false});




// ==============================
// FIND REAL CURRENT SECTION
// ==============================
const updatePreviouseSection = ()=> {

    previousSection = currentSection
}

const updateCurrentSection = ()=> {

    let closest = 0;
    let smallestDistance = Infinity;

    sections.forEach(function(section,index){



        const distance = Math.abs(
            window.scrollY - section.offsetTop
        );



        if(distance < smallestDistance){

            smallestDistance = distance;

            closest = index;

        }


        currentSection = closest
    
    });


    
}




// ==============================
// LIMIT SECTION NUMBER
// ==============================

function clampSection(){


    if(currentSection < 0){

        currentSection = 0;

    }



    if(currentSection >= sectionCount){

        currentSection = sectionCount - 1;

    }



}







// ==============================
// CUSTOM SMOOTH SCROLL
// ==============================

function scrollToSection(index){

    isScrolling = true;

    const start = window.scrollY;
    const target = sections[index].offsetTop;
    const distance = target - start;
    const duration = 1000;

    let startTime = null;


    function animate(time){



        if(startTime === null){

            startTime = time;

        }



        const elapsed = time - startTime;



        const progress = Math.min(
            elapsed / duration,
            1
        );



        const eased = easeInOut(progress);



        window.scrollTo(
            0,
            start + distance * eased
        );



        if(progress < 1){


            requestAnimationFrame(animate);


        }
        else{


            // Force exact position
            window.scrollTo(
                0,
                target
            );



            isScrolling = false;

            designAnimation();
            console.log("currentSection: " + currentSection);
        }
        
        
    }
    
    
    requestAnimationFrame(animate);
    
}





// ==============================
// SMOOTH CURVE
// ==============================

let easeInOut = (t)=> {
    
    
    return t < 0.5
    
    ? 4 * Math.pow(t, 3)
    
    : 1 - Math.pow(-2 * t + 2,3) / 2;
    
    
}

const logo = document.getElementById("logo")

const designAnimation = ()=> {

    if(currentSection >= previousSection && currentSection === 1) {
        logo.classList.add("active");
    } else if (currentSection <= previousSection && currentSection < 1) {
        logo.classList.remove("active");
    }

};  

