let number = 0;

function morph() {
    const nextShape = shapes[number];

    gsap.to(path, {
        duration: 3,
        ease: "power1.inOut",

        morphSVG: {
            shape: nextShape,
            shapeIndex: "auto"
        },

        onComplete: () => {
            number++;

            if (number >= shapes.length) {
                number = 0;
            }

            morph();
        }
    });
}

morph();

